window.Q_DATA=(window.Q_DATA||[]).concat([{"id":"R0802B-20","examCode":"R0802B","exam":"令和8年2月 B","number":20,"field":"アンテナ・電波伝搬","topic":"回線収支","answer":3,"image":"data:image/jpeg;base64,","text":"〔20〕 図に示すマイクロ波回線において、A 局から送信機出力電力0.5〔W〕で送信したときのB 局の受信機入力電力の値として、 最も近いものを下の番号から選べ。ただし、自由空間基本伝送損失を132〔dB〕、送信及び受信アンテナの絶対利得をそれぞれ 39〔dB〕、送信及び受信帯域フィルタ(BPF)の損失をそれぞれ1〔dB〕、送信及び受信給電線の長さをそれぞれ20〔m〕とし、給 電線損失を0.2〔dB/m〕とする。また、log₁₀2＝0.3 とする。 1 －31〔dBm〕 2 －34〔dBm〕 3 －37〔dBm〕 4 －40〔dBm〕 5 －43〔dBm〕 送信アンテナ 給電線 給電線 受信アンテナ 帯 域 フィルタ (BPF) A 局 B 局 送信機 受信機 帯 域 フィルタ (BPF)","explanation":"<div class=\"ex-id\">R0802B-20｜回線収支</div><h4>送信電力</h4><p>0.5W=<strong>27dBm</strong>。</p><h4>損失と利得</h4><p>送信BPF −1dB、送信給電線20m×0.2=−4dB、送信アンテナ+39dB、自由空間−132dB、受信アンテナ+39dB、受信給電線−4dB、受信BPF−1dB。</p><p>27−1−4+39−132+39−4−1=<strong>−37dBm</strong>。選択肢3です。</p><h4>検算</h4><p>アンテナ利得は送受信で合計+78dB、給電線は両側で−8dBです。片側分を落とすと数dBずれるので注意します。</p><h4>理解の補足</h4><p>回線収支は、送信点から受信機入力までの利得と損失をdBで帳簿のように足し引きする考え方です。送信電力をdBmまたはdBWへ直しておけば、アンテナ利得も伝送損失も同じ加減算で扱えます。</p><h4>試験での確認</h4><p>送信側給電線・受信側給電線、送信BPF・受信BPFのように左右対称の損失を片方だけ落としやすいです。経路を左から右へ一つずつ読み上げながら符号付きで並べると安全です。</p>","choices":5,"stemText":"図に示すマイクロ波回線において、 A 局から送信機出力電力0.5〔W〕で送信したときの B 局の受信機入力電力の値として、最も近いものを下の番号から選べ。ただし、自由空間基本伝送損失を132〔dB〕、送信及び受信アンテナの絶対利得をそれぞれ39〔dB〕、送信及び受信帯域フィルタ(BPF)の損失をそれぞれ1〔dB〕、送信及び受信給電線の長さをそれぞれ20〔m〕とし、給電線損失を0.2〔dB/m〕とする。また、log₁₀2＝0.3とする。","choiceTexts":["－31〔dBm〕","－34〔dBm〕","－37〔dBm〕","－40〔dBm〕","－43〔dBm〕"],"showFigure":true,"textExtractConfidence":"high","visualChoices":false,"solveMode":"calculation","calcLevel":"written","choiceReasons":["全ての利得・損失を含めた受信機入力は−37dBmです。−31dBmは6dB高すぎ、経路中の損失を合計6dB分落としたような値です。","−34dBmは正解より3dB高く、指定された損失の一部を計上していない値です。送受信両側のBPFと給電線をすべて含める必要があります。","0.5W=27dBmから−1−4+39−132+39−4−1を計算すると−37dBmです。この選択肢が正解です。","−40dBmは正解より3dB低く、指定外の損失を3dB余計に加えた値です。与えられた項目だけなら−37dBmになります。","−43dBmは正解より6dB低く、損失を合計6dB余分に見積もっています。回線収支は各項目を一度ずつ符号付きで加えるのが基本です。"]},{"id":"R0806A-03","examCode":"R0806A","exam":"令和8年6月 A","number":3,"field":"電気・電子回路","topic":"回路1","answer":4,"image":"data:image/jpeg;base64,","text":"〔３〕 図に示す回路において、端子 ab 間に直流電圧を加えたところ、端子 cd 間に 11.2〔V〕の電圧が現れた。16〔Ω〕の抵抗に流 れる電流 I〔A〕の値として、正しいものを下の番号から選べ。 1 0.2〔A〕 ａ 2 0.5〔A〕 I〔A〕 48〔Ω〕 16〔Ω〕 3 0.9〔A〕 ｃ 直流電圧 4 1.2〔A〕 5 3.7〔A〕 7〔Ω〕 11.2〔V〕 ｂ ｄ","explanation":"<div class=\"ex-id\">R0806A-03｜回路1</div><h4>下側から求める</h4><p>端子cd間11.2Vは7Ω抵抗の両端電圧なので、その枝電流は11.2/7=<strong>1.6A</strong>。この1.6Aが直列につながる上側並列ブロックへ流れます。</p><h4>上側並列</h4><p>48Ωと16Ωの並列合成は (48×16)/(48+16)=<strong>12Ω</strong>。ブロック電圧は1.6×12=<strong>19.2V</strong>。</p><p>16Ω枝の電流は19.2/16=<strong>1.2A</strong>。選択肢4です。</p><h4>理解の補足</h4><p>回路図では、式を覚えるより先に「同じ二点につながっているか」「一本道か」「分岐点か」を確認します。並列なら電圧が共通、直列なら電流が共通、分岐点では電流保存です。交流でLやCが入る場合だけ、位相を持つ量としてインピーダンスを扱います。</p><h4>試験での確認</h4><p>計算後は、求めた値を元の図へ戻してV=IRや電流保存が成立するかを一度確認すると、枝の取り違えをかなり防げます。単位もV・A・Ω・Wのどれを答えているか最後に確認します。</p>","choices":5,"stemText":"図に示す回路において、端子ab間に直流電圧を加えたところ、端子cd間に11.2〔V〕の電圧が現れた。16〔Ω〕の抵抗に流れる電流I〔A〕の値として、正しいものを下の番号から選べ。","choiceTexts":["0.2〔A〕","0.5〔A〕","0.9〔A〕","1.2〔A〕","3.7〔A〕"],"showFigure":true,"textExtractConfidence":"high","visualChoices":false,"sourceTextVerified":true,"solveMode":"calculation","calcLevel":"written","choiceReasons":["上側並列ブロックの電圧は19.2Vです。0.2Aなら16Ωの両端は3.2Vしかなく、同じ並列ブロックの電圧条件を満たしません。","0.5Aなら16Ω両端は8.0Vです。必要な19.2Vより大幅に低く、48Ω枝と同じ二点に接続された電圧になりません。","0.9Aなら16Ω両端は14.4Vです。上側並列部の19.2Vに届かないため誤りです。","下側7Ω枝から合成電流1.6A、上側48Ω∥16Ω=12Ωなので上側電圧は19.2Vです。16Ω枝は19.2/16=1.2Aとなり、この選択肢が正解です。","3.7Aなら16Ω両端は59.2Vとなり、上側並列部に必要な19.2Vを大きく超えます。"]},{"id":"R0806A-04","examCode":"R0806A","exam":"令和8年6月 A","number":4,"field":"電気・電子回路","topic":"デシベル","answer":2,"image":"data:image/jpeg;base64,","text":"〔４ 〕 次の記述は、デシベルを用いた計算について述べたものである。このうち正しいものを下の番号から選べ。ただし、 log 2 ＝ 0.3 とする。 10 1 1〔μV/m〕を 0〔dBμV/m〕としたとき、0.32〔mV/m〕の電界強度は 25〔dBμV/m〕である。 2 1〔mW〕を 0〔dBm〕としたとき、0.8〔W〕の電力は 29〔dBm〕である。 3 1〔μV〕を 0〔dBμV〕としたとき、5〔mV〕の電圧は 37〔dBμV〕である。 4 電圧比で最大値から 6〔dB〕下がったところの電圧レベルは、最大値の 1 / である。 5 出力電力が入力電力の 25 倍になる増幅回路の利得は 28〔dB〕である。 √2","explanation":"<div class=\"ex-id\">R0806A-04｜デシベル</div><h4>各選択肢</h4><ul><li>1：0.32mV/m=320μV/m →20log₁₀320=<strong>50dBμV/m</strong>。25ではない。</li><li>2：0.8W=800mW →10log₁₀800=<strong>29dBm</strong>。正しい。</li><li>3：5mV=5000μV →20log₁₀5000=<strong>74dBμV</strong>。37ではない。</li><li>4：−6dBの電圧比は1/2。1/√2は−3dB。</li><li>5：電力比25は10log₁₀25=<strong>14dB</strong>。28ではない。</li></ul><p>したがって正しいのは<strong>2</strong>です。</p><h4>理解の補足</h4><p>dBは「比」を対数で表す仕組みです。電力比は10log₁₀(P₂/P₁)を使います。電圧比を電力比から表す場合は、同一インピーダンスならP∝V²なので20log₁₀(V₂/V₁)になります。一方、dBμVやdBμV/mは、それぞれ1μV・1μV/mを基準にした振幅レベルなので、定義として20log₁₀を使います。</p><h4>試験での確認</h4><p>暗算では、電力2倍≈+3dB、4倍≈+6dB、10倍=+10dB、電圧2倍≈+6dBを軸にすると速いです。「10logか20logか」と「基準単位」を最初に決めるだけで、多くの誤答を切れます。</p>","choices":5,"stemText":"次の記述は、デシベルを用いた計算について述べたものである。このうち正しいものを下の番号から選べ。ただし、log₁₀2＝0.3とする。","choiceTexts":["1 μV/mを0dBμV/mとしたとき、0.32mV/mの電界強度は25dBμV/mである。","1mWを0dBmとしたとき、0.8Wの電力は29dBmである。","1 μVを0dBμVとしたとき、5mVの電圧は37dBμVである。","電圧比で最大値から6dB下がったところの電圧レベルは、最大値の1/√2である。","出力電力が入力電力の25倍になる増幅回路の利得は28dBである。"],"showFigure":false,"textExtractConfidence":"high","visualChoices":false,"solveMode":"text","calcLevel":"none","choiceReasons":["0.32 mV/mは320 μV/mなので、20log₁₀(320)≒50 dBμV/mです。25 dBμV/mではありません。","0.8W＝800mWです。dBmは1mWを0dBmとするので、10log₁₀(800)＝10{2＋log₁₀8}≒10(2＋0.9)＝29dBmとなります。したがってこの記述が正しいです。","5 mV＝5000 μVなので、20log10(5000)≒74 dBμVです。37 dBμVではありません。","電圧比では20log₁₀(V₂/V₁)を使います。−6 dBは約1/2であり、1/√2は−3 dBに相当します。","電力比25倍は10log10(25)≒14 dBです。28 dBではありません。"]},{"id":"R0806A-05","examCode":"R0806A","exam":"令和8年6月 A","number":5,"field":"電気・電子回路","topic":"共振回路","answer":1,"image":"data:image/jpeg;base64,","text":"〔５ 〕 次の記述は、図 1 及び図 2 に示す共振回路について述べたものである。このうち誤っているものを下の番号から選べ。ただ し、 〔rad/s〕は共振角周波数とする。 ω 0 1 図 1 の共振回路の Q(尖鋭度)は、Q = ω CR である。 0 1 L 2 図 1 の共振時の回路の 合成インピーダンスは、R である。 交 1 流 R 3 図 2 の共振回路の Q(尖鋭度)は、Q = 2 である。 電 R ω L 源 1 0 4 図 2 の共振角周波数 は、 = である。 C LC □ ω 0 ω 0 図 1 √ (JZ86A-1) 交 流 電 C R 2 L 源 図 2 R 、R :抵抗〔Ω〕 L :インダクタンス〔H〕 C :静電容量〔F〕 1 2","explanation":"<div class=\"ex-id\">R0806A-05｜共振回路</div><h4>基本式</h4><p>直列RLCのQは Q=ω₀L/R₁=1/(ω₀CR₁)。並列RLCは Q=R₂/(ω₀L)。</p><h4>各選択肢</h4><ul><li>1：「Q=ω₀CR₁」は<strong>誤り</strong>。正しくは1/(ω₀CR₁)。</li><li>2：直列共振時は合成インピーダンスR₁。正しい。</li><li>3：並列Q=R₂/(ω₀L)。正しい。</li><li>4：ω₀=1/√(LC)。正しい。</li></ul><p>よって誤っているのは<strong>1</strong>です。</p><h4>理解の補足</h4><p>共振は、コイルとコンデンサのリアクタンスが大きさとして等しくなり、互いの効果が打ち消し合う状態です。直列共振では入力から見たリアクタンスが消えるのでZが最小・Iが最大。並列共振では入力電流が小さくなり、入力インピーダンスが大きくなる方向です。</p><h4>試験での確認</h4><p>Qの式は、直列なら「リアクタンス÷抵抗」、並列なら「抵抗÷リアクタンス」と整理すると強いです。ω₀L=1/(ω₀C)も同時に覚えると、Qの等価な二つの式を相互変換できます。</p>","choices":4,"stemText":"次の記述は、図1及び図2に示す共振回路について述べたものである。このうち誤っているものを下の番号から選べ。ただし、ω₀〔rad/s〕は共振角周波数とする。","choiceTexts":["図1の共振回路のQ（尖鋭度）は、Q＝ω₀CR₁である。","図1の共振時の回路の合成インピーダンスは、R₁である。","図2の共振回路のQ（尖鋭度）は、Q＝R₂/(ω₀L)である。","図2の共振角周波数ω₀は、ω₀＝1/√(LC)である。"],"showFigure":true,"textExtractConfidence":"high","visualChoices":true,"choiceReasons":["図1は直列RLC回路なので、Q＝ω₀L/R₁＝1/(ω₀CR₁)です。したがってQ＝ω₀CR₁ではなく、その逆数側の1/(ω₀CR₁)が正しいため、この記述は誤りです。","直列共振ではLと C のリアクタンスが相殺されるため、図1の合成インピーダンスはR₁になります。","並列共振では共振条件 ω₀L＝1/(ω₀C) が成り立ち、Qは無効電流と抵抗電流の比から Q＝R₂/(ω₀L)＝ω₀CR₂ と表せます。したがって R₂/(ω₀L) は正しい式です。","共振条件ω₀L＝1/(ω₀ C )を解くと、図2の共振角周波数もω₀＝1/√(LC)になります。"],"solveMode":"text","calcLevel":"none"},{"id":"R0806A-12","examCode":"R0806A","exam":"令和8年6月 A","number":12,"field":"送受信・通信設備","topic":"雑音温度","answer":3,"image":"data:image/jpeg;base64,","text":"〔12 〕 2 段に縦続接続された増幅器の総合の等価雑音温度の値として、最も近いものを下の番号から選べ。ただし、初段の増幅器の 等価雑音温度を 270〔K〕、電力利得を 7〔dB〕、次段の増幅器の等価雑音温度を 400〔K〕とする。また、log 2 ＝ 0.3 とする。 10 1 315〔K〕 2 330〔K〕 3 350〔K〕 4 375〔K〕 5 410〔K〕","explanation":"<div class=\"ex-id\">R0806A-12｜雑音温度</div><h4>式</h4><p>2段縦続では T<sub>e</sub>=T₁+T₂/G₁。</p><h4>7dBを真数へ</h4><p>5倍の電力利得は10log₁₀5=10(1−log₁₀2)=10(1−0.3)=<strong>7dB</strong>。したがってG₁=5。</p><h4>計算</h4><p>T<sub>e</sub>=270+400/5=270+80=<strong>350K</strong>。選択肢3です。</p><h4>意味</h4><p>後段の400Kは初段利得5で割られて80K相当しか効きません。初段の性能が重要な理由です。</p><h4>理解の補足</h4><p>縦続回路では、後段が発生する雑音は初段利得で割られて入力側へ換算されます。だから初段で十分に増幅しておけば、後段の雑音が全体へ与える影響を小さくできます。</p><h4>試験での確認</h4><p>利得がdBで与えられたら、雑音温度式へ入れる前に必ず真数へ戻します。6dB→約4倍、7dB→約5倍のような変換を暗算できると速いです。</p>","choices":5,"stemText":"2段に縦続接続された増幅器の総合等価雑音温度の値として、最も近いものを下の番号から選べ。ただし、初段の増幅器の等価雑音温度を270〔K〕、電力利得を7〔dB〕、次段の増幅器の等価雑音温度を400〔K〕とする。また、log₁₀2＝0.3とする。","choiceTexts":["315〔K〕","330〔K〕","350〔K〕","375〔K〕","410〔K〕"],"showFigure":false,"textExtractConfidence":"high","visualChoices":false,"sourceTextVerified":true,"solveMode":"calculation","calcLevel":"written","choiceReasons":["7dBの初段利得は真数5倍なので、後段雑音400Kの入力換算分は80Kです。総合は350Kであり、315Kでは後段寄与を45Kまで小さく見積もりすぎています。","330Kなら後段寄与は60Kです。400/G1=60とするとG1≈6.67倍になり、実際の7dB=5倍と一致しません。","Te=270+400/5=350Kです。7dBを真数5へ戻して正しく入力換算した値なので、この選択肢が正解です。","375Kなら後段寄与は105Kとなり、初段利得を約3.8倍として扱った計算です。実際は5倍なので後段の影響を大きく見積もっています。","410Kでは後段寄与140Kとなり、初段利得を約2.86倍としたことになります。7dB=5倍を使っていないため誤りです。"]},{"id":"R0806A-19","examCode":"R0806A","exam":"令和8年6月 A","number":19,"field":"アンテナ・電波伝搬","topic":"半波長ダイポール","answer":3,"image":"data:image/jpeg;base64,","text":"〔19 〕 固有周波数 1,700〔MHz〕の半波長ダイポールアンテナの実効長の値として、最も近いものを下の番号から選べ。 1 1.9〔cm〕 2 2.8〔cm〕 3 5.6〔cm〕 4 11.2〔cm〕 5 16.9〔cm〕","explanation":"<div class=\"ex-id\">R0806A-19｜半波長ダイポール</div><h4>波長</h4><p>λ=c/f=3×10⁸/(1.7×10⁹)≈<strong>0.176m</strong>。</p><h4>実効長</h4><p>理想半波長ダイポールの最大実効長は l<sub>e</sub>=λ/π。</p><p>0.176/π≈0.056m=<strong>5.6cm</strong>。選択肢3です。</p><h4>注意</h4><p>実効長は物理的な全長λ/2とは別です。λ/2なら約8.8cmですが、本問で求めるのはλ/πです。</p><h4>理解の補足</h4><p>半波長ダイポールは基準アンテナとして頻出します。相対利得dBdは半波長ダイポール基準、絶対利得dBiは等方性アンテナ基準で、両者には約2.15dBの差があります。</p><h4>試験での確認</h4><p>実効長は物理長そのものではなく、受信電界から開放端電圧を換算するための量です。理想半波長ダイポールでは最大実効長λ/π。周波数が半分なら波長も実効長も2倍になります。</p>","choices":5,"stemText":"固有周波数1,700〔MHz〕の半波長ダイポールアンテナの実効長の値として、最も近いものを下の番号から選べ。","choiceTexts":["1.9〔cm〕","2.8〔cm〕","5.6〔cm〕","11.2〔cm〕","16.9〔cm〕"],"showFigure":false,"textExtractConfidence":"high","visualChoices":false,"solveMode":"calculation","calcLevel":"mental","choiceReasons":["1700MHzでは波長は約17.6cm、最大実効長はλ/π≈5.6cmです。1.9cmは約1/3しかなく、半波長ダイポールの実効長式と一致しません。","2.8cmは正しい実効長5.6cmの半分です。物理長や実効長の係数を取り違えた値で、λ/πにはなりません。","λ≈0.176mなのでle=λ/π≈0.056m=5.6cmです。この選択肢が正解です。","11.2cmは正しい実効長の2倍です。850MHzのように周波数が半分ならこの程度になりますが、1700MHzでは長すぎます。","16.9cmは波長約17.6cmに近い値で、実効長λ/πと波長そのものを混同した値です。"]},{"id":"R0806B-03","examCode":"R0806B","exam":"令和8年6月 B","number":3,"field":"電気・電子回路","topic":"回路1","answer":5,"image":"data:image/jpeg;base64,","text":"〔３〕 図に示す回路において、端子 ab 間に直流電圧を加えたところ、7.0〔Ω〕の抵抗に 1.5〔A〕の電流が流れた。端子 ab 間に加 えられた電圧の値として、正しいものを下の番号から選べ。 1 12〔V〕 7.0〔Ω〕 2 15〔V〕 3.5〔Ω〕 ａ ｂ 3 19〔V〕 4 24〔V〕 3.0〔Ω〕 5 28〔V〕","explanation":"<div class=\"ex-id\">R0806B-03｜回路1</div><h4>並列部の電圧</h4><p>7Ωに1.5Aが流れるので、その両端電圧は7×1.5=<strong>10.5V</strong>。並列の3Ωにも同じ10.5Vが加わります。</p><h4>合成電流</h4><p>3Ωの電流は10.5/3=<strong>3.5A</strong>。7Ω枝1.5Aと合わせて、直列部分を流れる電流は<strong>5A</strong>。</p><h4>直列部分</h4><p>3.5Ωの電圧降下は5×3.5=<strong>17.5V</strong>。よって端子ab間は10.5+17.5=<strong>28V</strong>。選択肢5です。</p><h4>理解の補足</h4><p>回路図では、式を覚えるより先に「同じ二点につながっているか」「一本道か」「分岐点か」を確認します。並列なら電圧が共通、直列なら電流が共通、分岐点では電流保存です。交流でLやCが入る場合だけ、位相を持つ量としてインピーダンスを扱います。</p><h4>試験での確認</h4><p>計算後は、求めた値を元の図へ戻してV=IRや電流保存が成立するかを一度確認すると、枝の取り違えをかなり防げます。単位もV・A・Ω・Wのどれを答えているか最後に確認します。</p>","choices":5,"stemText":"図に示す回路において、端子ab間に直流電圧を加えたところ、7.0〔Ω〕の抵抗に1.5〔A〕の電流が流れた。端子ab間に加えられた電圧の値として、正しいものを下の番号から選べ。","choiceTexts":["12〔V〕","15〔V〕","19〔V〕","24〔V〕","28〔V〕"],"showFigure":true,"textExtractConfidence":"high","visualChoices":false,"sourceTextVerified":true,"solveMode":"calculation","calcLevel":"written","choiceReasons":["並列部だけで7Ω×1.5A=10.5V必要です。12Vでは残りの直列3.5Ω部分に1.5Vしか残らず、合成電流5Aによる17.5Vの電圧降下を賄えません。","並列部は10.5V、直列3.5Ω部分は17.5V必要です。15Vでは全体28Vに13V不足します。","19Vでも、必要な10.5+17.5=28Vより9V低く、各枝のV=IRと電流保存を同時に満たしません。","24Vは正しい28Vより4V低く、直列部分の電圧降下17.5Vを含めると不足します。","7Ω枝から並列部10.5V、3Ω枝3.5A、合成5A、直列3.5Ωで17.5Vです。合計28Vとなるため、この選択肢が正解です。"]},{"id":"R0806B-04","examCode":"R0806B","exam":"令和8年6月 B","number":4,"field":"電気・電子回路","topic":"デシベル","answer":3,"image":"data:image/jpeg;base64,","text":"〔４〕 次の記述は、デシベルを用いた計算について述べたものである。このうち誤っているものを下の番号から選べ。ただし、 log 2 ＝ 0.3 とする。 10 1 1〔mW〕を 0〔dBm〕としたとき、8〔W〕の電力は 39〔dBm〕である。 2 1〔μV〕を 0〔dBμV〕としたとき、0.5〔mV〕の電圧は 54〔dBμV〕である。 3 1〔μV/m〕を 0〔dBμV/m〕としたとき、3.2〔mV/m〕の電界強度は 63〔dBμV/m〕である。 4 出力電力が入力電力の 250 倍になる増幅回路の利得は 24〔dB〕である。 5 電圧比で最大値から 6〔dB〕下がったところの電圧レベルは、最大値の 1 / 2 である。","explanation":"<div class=\"ex-id\">R0806B-04｜デシベル</div><h4>各選択肢</h4><ul><li>1：8W=8000mW →39dBm。正しい。</li><li>2：0.5mV=500μV →20log₁₀500=<strong>54dBμV</strong>。正しい。</li><li>3：3.2mV/m=3200μV/m →20log₁₀3200=<strong>70dBμV/m</strong>。63dBではないので誤り。</li><li>4：電力比250=1000/4 →30−6=<strong>24dB</strong>。正しい。</li><li>5：電圧比1/2は約−6dB。正しい。</li></ul><p>したがって誤っているのは<strong>3</strong>です。</p><h4>理解の補足</h4><p>dBは「比」を対数で表す仕組みです。電力比は10log₁₀(P₂/P₁)を使います。電圧比を電力比から表す場合は、同一インピーダンスならP∝V²なので20log₁₀(V₂/V₁)になります。一方、dBμVやdBμV/mは、それぞれ1μV・1μV/mを基準にした振幅レベルなので、定義として20log₁₀を使います。</p><h4>試験での確認</h4><p>暗算では、電力2倍≈+3dB、4倍≈+6dB、10倍=+10dB、電圧2倍≈+6dBを軸にすると速いです。「10logか20logか」と「基準単位」を最初に決めるだけで、多くの誤答を切れます。</p>","choices":5,"stemText":"次の記述は、デシベルを用いた計算について述べたものである。このうち誤っているものを下の番号から選べ。ただし、log₁₀2＝0.3とする。","choiceTexts":["1mWを0dBmとしたとき、8Wの電力は39dBmである。","1 μVを0dBμVとしたとき、0.5mVの電圧は54dBμVである。","1 μV/mを0dBμV/mとしたとき、3.2mV/mの電界強度は63dBμV/mである。","出力電力が入力電力の250倍になる増幅回路の利得は24dBである。","電圧比で最大値から6dB下がったところの電圧レベルは、最大値の1/2である。"],"showFigure":false,"textExtractConfidence":"high","visualChoices":false,"solveMode":"text","calcLevel":"none","choiceReasons":["8W＝8000mWです。dBmは1mW基準なので、10log₁₀(8000)＝10{3＋log₁₀8}≒10(3＋0.9)＝39dBmとなり、この記述は正しいです。","0.5 mV＝500 μVなので、20log10(500)≒54 dBμVです。","3.2 mV/mは3,200 μV/mなので、20log₁₀(3,200)≒70 dBμV/mです。63 dBμV/mではありません。","電力比250倍の利得は10log₁₀(250)です。250＝1000/4なので、30−6≒24dBとなります。したがってこの記述は正しいです。","電圧比の−6 dBは10^(−6/20)≒0.50なので、最大電圧の約1/2です。"]}]);
